    "expl.ex2.detail": ["{start} + 45 h. Les heures 40 à 43 sont à majorer 25 %, les heures 44 et 45 à majorer 50 %.", "{start} + 45 h. Hours 40 to 43 are overtime at 25 %, hours 44 and 45 at 50 %.", "{start} + 45 h. Las horas 40 a 43 se recargan al 25 %, las horas 44 y 45 al 50 %.", "{start} + 45 h. Die Stunden 40 bis 43 sind Überstunden zu 25 %, die Stunden 44 und 45 zu 50 %."],
    "expl.ex3.title": ["Exemple 3 — Semaine avec un jour férié, 39 h travaillées", "Example 3 — Week with a public holiday, 39 h worked", "Ejemplo 3 — Semana con un festivo, 39 h trabajadas", "Beispiel 3 — Woche mit Feiertag, 39 h gearbeitet"],
    "expl.ex3.detail": ["Le férié ajoute {day} : 39 h + {day} = {done} faites. Les heures à majorer ne portent que sur les heures réellement travaillées.", "The holiday adds {day}: 39 h + {day} = {done} done. Overtime only applies to hours actually worked.", "El festivo suma {day}: 39 h + {day} = {done} hechas. Las horas a recargar solo se aplican a las horas realmente trabajadas.", "Der Feiertag fügt {day} hinzu: 39 h + {day} = {done} geleistet. Überstunden betreffen nur tatsächlich gearbeitete Stunden."],
    "expl.ex4.title": ["Exemple 4 — Semaine courte de 35 h", "Example 4 — Short 35 h week", "Ejemplo 4 — Semana corta de 35 h", "Beispiel 4 — Kurze 35-Stunden-Woche"],
    "expl.ex4.detail": ["{start} + 35 h : il manque des heures, déduites du total.", "{start} + 35 h: hours are missing, deducted from the total.", "{start} + 35 h: faltan horas, que se restan del total.", "{start} + 35 h: Es fehlen Stunden, die von der Summe abgezogen werden."],
    "expl.ex5.title": ["Exemple 5 — Journée avec repas", "Example 5 — Day with meal", "Ejemplo 5 — Día con comida", "Beispiel 5 — Tag mit Mahlzeit"],
    "expl.ex5.detail": ["10 h pointées dont 1 h de « Repas » : le repas n'est pas payé, il est déduit.", "10 h clocked including 1 h of \"Meal\": the meal is not paid, it is deducted.", "10 h fichadas con 1 h de «Comida»: la comida no se paga, se descuenta.", "10 h erfasst, davon 1 h „Mahlzeit“: Die Mahlzeit wird nicht bezahlt und abgezogen."],
    "expl.ex5.result": ["10 h − 1 h repas = 9 h, journée finie", "10 h − 1 h meal = 9 h, day done", "10 h − 1 h comida = 9 h, jornada terminada", "10 h − 1 h Mahlzeit = 9 h, Tag beendet"],
    "expl.ex6.title": ["Exemple 6 — Semaine avec 2 jours de récupération", "Example 6 — Week with 2 days of time off", "Ejemplo 6 — Semana con 2 días de recuperación", "Beispiel 6 — Woche mit 2 Ausgleichstagen"],
    "expl.ex6.detail": ["3 jours de 8 h travaillés (24 h) + 2 jours de récupération × {day} = {credit} : {done} faites.", "3 days of 8 h worked (24 h) + 2 time-off days × {day} = {credit}: {done} done.", "3 días de 8 h trabajados (24 h) + 2 días de recuperación × {day} = {credit}: {done} hechas.", "3 Tage à 8 h gearbeitet (24 h) + 2 Ausgleichstage × {day} = {credit}: {done} geleistet."],
    "expl.ex6.result": ["les {credit} sont retirées du solde de récupération", "the {credit} are taken from the time-off balance", "las {credit} se restan del saldo de recuperación", "die {credit} werden vom Ausgleichssaldo abgezogen"],
    "expl.ex7.title": ["Exemple 7 — Mardi de 21 h à 1 h du matin", "Example 7 — Tuesday from 21:00 to 01:00", "Ejemplo 7 — Martes de 21 h a 1 h de la madrugada", "Beispiel 7 — Dienstag von 21 bis 1 Uhr"],
    "expl.ex7.detail": ["4 h de nuit (3 h le mardi, 1 h le mercredi), comptées dans la semaine, plus une majoration de 25 %.", "4 night hours (3 h on Tuesday, 1 h on Wednesday), counted in the week, plus a 25 % premium.", "4 h nocturnas (3 h el martes, 1 h el miércoles), contadas en la semana, más un recargo del 25 %.", "4 Nachtstunden (3 h am Dienstag, 1 h am Mittwoch), in der Woche gezählt, plus 25 % Zuschlag."],
    "expl.ex8.title": ["Exemple 8 — Jour férié travaillé de 20 h à 23 h", "Example 8 — Public holiday worked from 20:00 to 23:00", "Ejemplo 8 — Festivo trabajado de 20 h a 23 h", "Beispiel 8 — Gearbeiteter Feiertag von 20 bis 23 Uhr"],
    "expl.ex8.detail": ["3 h comptées dans la semaine, plus 50 %. Les 2 h de nuit ne sont pas majorées en plus.", "3 h counted in the week, plus 50 %. The 2 night hours do not get an extra premium.", "3 h contadas en la semana, más un 50 %. Las 2 h nocturnas no reciben recargo adicional.", "3 h in der Woche gezählt, plus 50 %. Die 2 Nachtstunden erhalten keinen zusätzlichen Zuschlag."],
    "expl.ex9.title": ["Exemple 9 — Dimanche de 8 h à 11 h", "Example 9 — Sunday from 08:00 to 11:00", "Ejemplo 9 — Domingo de 8 h a 11 h", "Beispiel 9 — Sonntag von 8 bis 11 Uhr"],
    "expl.ex9.detail": ["La semaine va du lundi au dimanche : les 3 h du dimanche s'ajoutent aux heures faites.", "The week runs from Monday to Sunday: the 3 Sunday hours are added to the hours done.", "La semana va de lunes a domingo: las 3 h del domingo se suman a las horas hechas.", "Die Woche geht von Montag bis Sonntag: Die 3 Sonntagsstunden kommen zu den geleisteten Stunden hinzu."],
    "expl.ex9.result": ["Ajouté à la semaine : 3 h", "Added to the week: 3 h", "Sumado a la semana: 3 h", "Zur Woche addiert: 3 h"],
    "expl.ex10.title": ["Exemple 10 — Jour de récupération accordé mais travaillé", "Example 10 — Approved time-off day that was worked", "Ejemplo 10 — Día de recuperación aprobado pero trabajado", "Beispiel 10 — Genehmigter, aber gearbeiteter Ausgleichstag"],
    "expl.ex10.detail": ["Les heures travaillées comptent normalement ; la récupération n'est ni créditée ni retirée du solde. Une récupération non travaillée ajoute {day} à la semaine et retire {day} du solde.", "The hours worked count normally; the time off is neither credited nor taken from the balance. Time off that is not worked adds {day} to the week and takes {day} from the balance.", "Las horas trabajadas cuentan normalmente; la recuperación no se acredita ni se resta del saldo. Una recuperación no trabajada suma {day} a la semana y resta {day} del saldo.", "Die gearbeiteten Stunden zählen normal; der Ausgleich wird weder gutgeschrieben noch vom Saldo abgezogen. Ein nicht gearbeiteter Ausgleichstag bringt {day} zur Woche und zieht {day} vom Saldo ab."],
    "expl.ex10.result": ["Pas de double décompte", "No double count", "Sin doble cómputo", "Keine Doppelzählung"],

